    if not cwd.startswith('/'):
        return None
    cwd = cwd.rstrip('/') or '/'

    # Start with cwd if path is relative, otherwise use path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if candidate is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Process remaining components plus target
            if target.startswith('/'):
                current = '/'
                new_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    link_dir = '/'
                else:
                    link_dir = candidate.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'
                current = link_dir
                new_components = target.split('/')

            # Replace components: keep processed ones, add target components, keep remaining
            components = components[:i] + new_components + components[i+1:]
            i = 0
            continue

        # Regular component - update current
        current = candidate
        i += 1

    # Return canonical path (no trailing slash except for root)
    if current == '':
        current = '/'
    return current

